solution:
public User getUser(String id) {
    String key = "user:" + id;
    User cached = cache.get(key);
    if (cached != null) {
        return cached; // hit : on renvoie la valeur du cache
    }
    User user = repository.findById(id); // miss : on charge la source
    cache.put(key, user);                // on remplit le cache au passage
    return user;
}
